<template>
  <AdminLayout>
    <div class="console"><aside class="side-nav"><div class="side-title"><span>控制台</span><small>OPERATIONS CONSOLE</small></div><button v-for="item in navItems" :key="item.key" :class="{active: activeTab === item.key}" @click="activeTab = item.key"><span>{{ item.icon }}</span>{{ item.label }}<b v-if="item.badge">{{ item.badge }}</b></button><div class="side-foot"><span class="pulse"></span> 管理服务正常<small>配置变更将记录审计日志</small></div></aside><main class="admin-main"><header class="content-head"><div><p class="eyebrow">PLATFORM OPERATIONS</p><h1>{{ currentTitle }}</h1><p>{{ currentSubtitle }}</p></div><div class="head-actions"><span class="clock">{{ nowText }}</span><button @click="load" :disabled="loading">{{ loading ? '同步中…' : '↻ 刷新状态' }}</button></div></header><section class="summary-grid"><div><span>连接服务器</span><strong>{{ infrastructure?.servers.length || 0 }}</strong><small>数据库 / NWP 文件源</small></div><div><span>目标场站</span><strong>{{ stations.length }}</strong><small>{{ enabledCount }} 个已启用</small></div><div><span>数据源</span><strong>{{ sources.length }}</strong><small>{{ onlineSources }} 个配置正常</small></div><div><span>审计事件</span><strong>{{ logs.length }}</strong><small>最近配置操作</small></div></section>
      <section v-if="activeTab === 'overview'" class="tab-content"><div class="section-title"><div><h2>平台运行总览</h2><p>连接、数据源和场站配置的统一入口</p></div><span class="live-label"><i></i>管理接口在线</span></div><div class="server-grid"><article v-for="server in infrastructure?.servers || []" :key="server.id" class="server-card"><div class="server-top"><div><span class="server-kind">{{ server.kind }}</span><h3>{{ server.name }}</h3></div><strong :class="server.status">{{ server.status === 'configured' ? '已配置' : '配置不完整' }}</strong></div><div class="server-address"><span>{{ server.host }}</span><b>:{{ server.port }}</b></div><div class="server-meta"><span>账户 <b>{{ server.account }}</b></span><span>{{ server.id === 'mysql' ? '数据库' : '远程目录' }} <b>{{ server.database }}</b></span></div><div class="server-foot"><span>认证信息</span><b>{{ server.secret }}</b><button @click="checkServer(server.id)">检查连接</button></div></article></div><div class="overview-columns"><section class="inner-panel"><div class="inner-head"><h3>数据源健康度</h3><button @click="activeTab='sources'">查看全部 ↗</button></div><div v-for="source in sources" :key="source.name" class="source-row"><span class="source-dot" :class="source.status"></span><div><b>{{ source.title || source.name }}</b><small>{{ source.note }}</small></div><strong>{{ source.label }}</strong></div></section><section class="inner-panel"><div class="inner-head"><h3>最近审计</h3><button @click="activeTab='audit'">查看日志 ↗</button></div><div v-for="log in logs.slice(0,4)" :key="log.created_at" class="audit-mini"><span>{{ log.action }}</span><b>{{ log.station_id }}</b><time>{{ new Date(log.created_at).toLocaleString('zh-CN') }}</time></div><div v-if="!logs.length" class="empty">暂无配置操作记录</div></section></div></section>
      <section v-else-if="activeTab === 'servers'" class="tab-content"><div class="section-title"><div><h2>服务器连接管理</h2><p>仅展示连接元数据，密码和 SSH 私钥不会在页面回显</p></div></div><div class="server-grid expanded"><article v-for="server in infrastructure?.servers || []" :key="server.id" class="server-card"><div class="server-top"><div><span class="server-kind">{{ server.kind }}</span><h3>{{ server.name }}</h3></div><strong :class="server.status">{{ server.status === 'configured' ? '已配置' : '配置不完整' }}</strong></div><dl><div><dt>主机</dt><dd>{{ server.host }}</dd></div><div><dt>端口</dt><dd>{{ server.port }}</dd></div><div><dt>账户</dt><dd>{{ server.account }}</dd></div><div><dt>{{ server.id === 'mysql' ? '数据库' : '远程目录' }}</dt><dd>{{ server.database }}</dd></div><div><dt>认证</dt><dd>{{ server.secret }}</dd></div></dl><button class="primary-action" @click="checkServer(server.id)">检查连接</button><button @click="editServer(server.id)">编辑配置</button></article></div><div class="security-note">安全提示：实际密码、数据库密钥和 SSH 私钥保存在后端环境变量/密钥文件中，后台只提供状态核验，不提供明文查看。</div></section>
      <section v-else-if="activeTab === 'sources'" class="tab-content"><div class="section-title"><div><h2>数据源管理</h2><p>功率、预测、历史观测和 NWP 文件源状态</p></div></div><div class="source-cards"><article v-for="source in sources" :key="source.name"><div><span class="source-dot" :class="source.status"></span><h3>{{ source.title || source.name }}</h3></div><strong>{{ source.label }}</strong><p>{{ source.note }}</p><footer>最后检查：{{ nowText }} <button @click="checkServer(source.name)">刷新</button></footer></article></div></section>
      <section v-else-if="activeTab === 'stations'" class="tab-content"><div class="section-title"><div><h2>场站资产管理</h2><p>启用状态会影响大屏资产范围和统计汇总</p></div><span class="table-count">{{ enabledCount }} / {{ stations.length }} 已启用</span></div><div class="table-panel"><el-table :data="stations" stripe><el-table-column prop="station_id" label="场站" width="120"/><el-table-column prop="station_type" label="类型" width="100"><template #default="scope"><span class="type-tag">{{ scope.row.station_type === 'pv' ? '光伏' : '风电' }}</span></template></el-table-column><el-table-column prop="capacity_mw" label="装机容量 (MW)"/><el-table-column prop="longitude" label="经度"/><el-table-column prop="latitude" label="纬度"/><el-table-column label="运行状态" width="140"><template #default="scope"><el-switch v-model="scope.row.enabled" inline-prompt active-text="启用" inactive-text="停用" @change="save(scope.row)" /></template></el-table-column></el-table></div></section>
      <section v-else class="tab-content"><div class="section-title"><div><h2>审计日志</h2><p>记录场站配置和后台操作，可用于追溯变更</p></div></div><div class="table-panel audit-table"><div class="audit-head"><span>操作</span><span>对象</span><span>变更前</span><span>变更后</span><span>时间</span></div><div v-for="log in logs" :key="log.created_at" class="audit-line"><b>{{ log.action }}</b><span>{{ log.station_id }}</span><code>{{ JSON.stringify(log.before) }}</code><code>{{ JSON.stringify(log.after) }}</code><time>{{ new Date(log.created_at).toLocaleString('zh-CN') }}</time></div><div v-if="!logs.length" class="empty">暂无审计记录</div></div></section>
    </main></div>
  </AdminLayout>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import AdminLayout from '../../layouts/AdminLayout.vue'
import { http } from '../../api/http'
import type { Station } from '../../api/types'
type ServerInfo = { id: string; name: string; kind: string; host: string; port: number; account: string; database: string; status: string; secret: string }
type Infra = { servers: ServerInfo[]; runtime: { timezone: string; realtime_interval_seconds: number } }
const activeTab = ref('overview'); const stations = ref<Station[]>([]); const logs = ref<any[]>([]); const infrastructure = ref<Infra>(); const loading = ref(false); const now = ref(new Date())
const navItems = computed(() => [{ key: 'overview', icon: '⌂', label: '运行总览' }, { key: 'servers', icon: '◈', label: '服务器连接', badge: infrastructure.value?.servers.length || 2 }, { key: 'sources', icon: '◉', label: '数据源管理' }, { key: 'stations', icon: '⌁', label: '场站资产' }, { key: 'audit', icon: '≡', label: '审计日志', badge: logs.value.length || undefined }])
const titles: Record<string, [string, string]> = { overview: ['平台运行总览', '新能源消纳与并网控制平台 · 运维控制台'], servers: ['服务器连接管理', '管理数据库和远程气象文件源的连接元数据'], sources: ['数据源管理', '查看实时接口、预测结果和 NWP 文件源状态'], stations: ['场站资产管理', '管理目标场站启用范围和基础信息'], audit: ['审计日志', '配置变更和操作记录可追溯'] }; const currentTitle = computed(() => titles[activeTab.value][0]); const currentSubtitle = computed(() => titles[activeTab.value][1]); const enabledCount = computed(() => stations.value.filter(item => item.enabled).length); const onlineSources = computed(() => sources.value.filter(item => item.status === 'ok').length); const nowText = computed(() => now.value.toLocaleTimeString('zh-CN', { hour12: false })); type SourceRow = { name: string; title: string; label: string; status: 'ok' | 'warn' | 'bad'; note: string }; const sources = ref<SourceRow[]>([])
const SOURCE_TITLES: Record<string, string> = { mysql: 'MySQL 功率与预测库', 'nwp-files': 'NWP 文件快照' }
const STATUS_LABELS: Record<string, string> = { connected: '已连接', stale: '数据过期', missing: '未同步', error: '连接失败', incomplete: '未配置', unreachable: '服务不可达' }
function mapSource(row: { name: string; label?: string; status: string; detail?: string }): SourceRow { const status = row.status === 'connected' ? 'ok' : (row.status === 'stale' ? 'warn' : 'bad'); return { name: row.name, title: row.label || SOURCE_TITLES[row.name] || row.name, label: STATUS_LABELS[row.status] || row.status, status, note: row.detail || '' } }
async function loadSources() { try { sources.value = (await http.get<any[]>('/admin/data-sources/status')).data.map(mapSource) } catch { sources.value = [] } }
async function load() { loading.value = true; try { const result = await Promise.all([http.get<Station[]>('/admin/stations'), http.get<any[]>('/admin/audit-logs'), http.get<Infra>('/admin/infrastructure'), loadSources()]); stations.value = result[0].data; logs.value = result[1].data; infrastructure.value = result[2].data } finally { loading.value = false } }
async function save(row: Station) { await http.patch(`/admin/stations/${row.station_id}`, { enabled: row.enabled }); logs.value = (await http.get<any[]>('/admin/audit-logs')).data }
async function checkServer(id: string) { const serverId = id === 'nwp-files' ? 'nwp' : id; loading.value = true; try { const result = (await http.post(`/admin/infrastructure/${serverId}/test`)).data; await loadSources(); logs.value = (await http.get<any[]>('/admin/audit-logs')).data; const label = STATUS_LABELS[result.status] || result.status; ElMessage({ type: result.status === 'connected' ? 'success' : 'warning', message: `${serverId}：${label} ${result.detail || ''}` }) } finally { loading.value = false } }
async function editServer(id: string) { const server = infrastructure.value?.servers.find(entry => entry.id === id); if (!server) return; const ask = async (message: string, value: string) => { try { return (await ElMessageBox.prompt(message, '编辑服务器连接配置', { inputValue: value, confirmButtonText: '下一步', cancelButtonText: '取消' })).value } catch { return null } }; const host = await ask('主机地址', server.host); if (host == null || !host.trim()) return; const portText = await ask('端口', String(server.port)); const port = Number(portText); if (!Number.isInteger(port) || port < 1 || port > 65535) { ElMessage.error('端口必须在 1-65535 范围内'); return } const account = await ask('账户（密码不会在此处修改）', server.account); const database = await ask(id === 'mysql' ? '数据库名' : '远程目录', server.database); if (account == null || database == null) return; loading.value = true; try { await http.patch(`/admin/infrastructure/${id}`, { host: host.trim(), port, account: account.trim(), database: database.trim() }); await load(); ElMessage.success('服务器连接配置已保存并写入审计日志') } finally { loading.value = false } }
onMounted(() => { load(); window.setInterval(() => { now.value = new Date() }, 1000) })
</script>
